const componentPartCandidates = (paths, parentPath, base, componentId) => {
  const prefix = `${base}_Part${componentId + 1}`, candidates = [];
  for (const path of paths) {
    const separator = path.lastIndexOf('/');
    if (path.slice(0, separator) !== (parentPath === '/' ? '' : parentPath)) continue;
    const leaf = path.slice(separator + 1), suffix = leaf.slice(prefix.length);
    if (leaf !== prefix && (!suffix.startsWith('_') || suffix.slice(1).split('_').some((part) => !/^\d+$/.test(part)))) continue;
    const rank = leaf === prefix ? [-1, -1] : (() => { const values = suffix.slice(1).split('_').map(Number); return [values[0], values[1] ?? -1]; })();
    candidates.push({ path, rank });
  }
  return candidates.sort((a, b) => a.rank[0] - b.rank[0] || a.rank[1] - b.rank[1] || a.path.localeCompare(b.path)).map(({ path }) => path);
};

