    this.$('#comparison-heatmap').onclick = ({ target }) => { if (this.bridge.comparisonHeatmap) { this.bridge.restoreBeforeAfter(); target.textContent = 'Show surface-distance heatmap'; } else { this.bridge.showSurfaceDistanceHeatmap(this.bridge.comparisonData); target.textContent = 'Show wipe compare'; } };
    this.$('#comparison-material').onclick = ({ target }) => { if (this.bridge.comparisonMaterial) { this.bridge.restoreBeforeAfter(); target.textContent = 'Show material difference'; } else if (this.bridge.showMaterialDifference(this.bridge.materialBefore, this.bridge.materialAfter)) target.textContent = 'Show wipe compare'; };
    this.$('#comparison-clear').onclick = () => { this.bridge.clearChangeOverlay(); this.bridge.comparisonEdges = null; this.bridge.comparisonData = null; this.bridge.materialBefore = null; this.bridge.materialAfter = null; this.bridge.comparisonGhost = false; this.bridge.comparisonMaterial = false; this.$('#comparison-control').hidden = true; this.$('#comparison-ghost').hidden = true; this.$('#comparison-ghost').textContent = 'Show ghost overlay'; this.$('#comparison-heatmap').hidden = true; this.$('#comparison-heatmap').textContent = 'Show surface-distance heatmap'; this.$('#comparison-material').hidden = true; this.$('#comparison-material').textContent = 'Show material difference'; this.$('#comparison-clear').hidden = true; };
    this.$('#frame-all-button').onclick = () => this.bridge.frameAll();
    this.$('#validation-status').onclick = () => this.runValidation();
    this.$('#cancel-operation').onclick = () => { if (this.operations) this.operations.cancel(); else this.setBusy(false); };
    this.$('#health-button').onclick = () => this.showHealthReport();
    this.$('#usd-doctor-button').onclick = () => this.showUSDDoctor();
    this.$('#transfer-uv-button').onclick = () => this.$('#transfer-dialog').showModal();
    this.$('#transfer-confirm').onclick = async () => {
      const sourcePath = this.$('#transfer-source').value.trim(), uvSet = this.$('#transfer-uv-set').value, targetPath = this.project.selectedPath;
      if (!sourcePath || !validPrimPath(sourcePath) || sourcePath === targetPath) { this.showError(new LuciaError('LUCIA_TRANSFER_PATH', 'Choose a different valid source mesh path.')); return; }
      this.$('#transfer-dialog').close();
      if (await this.confirmAction(`Transfer ${uvSet === 'lightmap' ? 'lightmap ' : ''}UVs from ${sourcePath} to ${targetPath}?`, 'Source UVs will be projected through the LightRT WASM BVH and authored on the selected UV set. The operation is undoable.')) await this.runMutation('Transfer UVs', [targetPath, sourcePath], () => this.operations.transferUVs(targetPath, sourcePath, { uvSet }, (p) => this.setBusy(true, p.message, p.percentage)));
    };
    this.$('#create-prim').onclick = () => this.$('#create-dialog').showModal();
