    const bindTabKeyboard = (selector, activate) => { const tabs = this.$$(selector); tabs.forEach((button, index) => { button.onclick = () => activate(button); button.onkeydown = (event) => { if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault(); const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; tabs[next].focus(); tabs[next].click(); }; }); };
